source('/home/jinshengxi/bladder_metabolism/results/llps_C5_cellchat_v2/scripts/common.R')
manifest<-fread(file.path(OUT,'00_audit/manifest.csv'));oldstat<-fread(file.path(OUT,'00_audit/source_object_stat.csv'),colClasses=c(mtime='character'));stopifnot(all(oldstat$size==file.info(oldstat$path)$size),all(abs(as.numeric(as.POSIXct(as.character(oldstat$mtime),tz=Sys.timezone()))-as.numeric(file.info(oldstat$path)$mtime))<1e-5))
checks<-list();k<-0L;add<-function(name,ok){stopifnot(ok);k<<-k+1L;checks[[k]]<<-data.table(check=name,pass=ok)}
for(i in seq_len(nrow(manifest))){u<-readRDS(file.path(OUT,'00_audit/unfiltered',paste0(manifest$run_id[i],'.rds')));pa<-u$options$parameter;add(paste(manifest$run_id[i],'actual native parameters'),pa$type.mean=='truncatedMean'&&pa$trim==.1&&identical(pa$population.size,FALSE)&&identical(pa$raw.use,TRUE)&&pa$nboot==100&&pa$seed.use==123);add(paste(manifest$run_id[i],'latest patient metadata'),all(u$meta$patient_id==manifest$patient_id[i])&&all(u$meta$specimen_id==manifest$specimen_id[i])&&all(u$meta$clinical_group==manifest$clinical_group[i]));}
for(t in c(10,20,30)){
 st<-fread(file.path(TD(t),'sample_status.csv'));add(paste(t,'59 successes'),nrow(st)==59&&all(st$status=='SUCCESS'))
 net<-fread(file.path(TD(t),'network_all_specimens.csv'));add(paste(t,'full 14x14'),nrow(net)==59*196);add(paste(t,'strict eligibility'),all(net$eligible==(net$sender_cells>t&net$receiver_cells>t)));add(paste(t,'NA ineligible'),all(is.na(net[eligible==FALSE,weight])));add(paste(t,'finite eligible'),all(is.finite(net[eligible==TRUE,weight])))
 c5<-unique(net[sender=='Fibro_C5'&sender_cells>t,.(specimen_id,patient_id)]);add(paste(t,'C5 specimens'),nrow(c5)==c(17,14,10)[match(t,c(10,20,30))]);add(paste(t,'C5 patients'),uniqueN(c5$patient_id)==c(15,13,10)[match(t,c(10,20,30))])
 prior<-fread(file.path(AUD,'cellchat_threshold_eligibility.csv'))[min_cells==t&target!='C5_only'];prior[,`:=`(sender=ifelse(sender=='C5','Fibro_C5',sender),target=ifelse(target=='C5','Fibro_C5',target))];chk<-merge(prior[,.(specimen_id,sender,receiver=target,audit_eligible=eligible)],net[,.(specimen_id,sender,receiver,eligible)],by=c('specimen_id','sender','receiver'));add(paste(t,'previous audit agrees'),nrow(chk)==59*14&&all(chk$audit_eligible==chk$eligible))
 for(i in seq_len(nrow(manifest))){z<-readRDS(file.path(TD(t),manifest$run_id[i],'compact_networks.rds'));ne<-net[specimen_id==manifest$specimen_id[i]];fw<-fc<-matrix(NA_real_,14,14,dimnames=list(GROUPS,GROUPS));ij<-cbind(match(ne$sender,GROUPS),match(ne$receiver,GROUPS));fw[ij]<-ne$weight;fc[ij]<-ne$LR_count;atomicRDS(list(weight=fw,count=fc,metadata=manifest[i],min_cells=t),file.path(TD(t),manifest$run_id[i],'network_14x14.rds'));pr<-z$net$prob;pv<-z$net$pval;add(paste(t,manifest$run_id[i],'finite arrays'),all(is.finite(pr))&&all(pr>=0)&&all(is.finite(pv))&&all(pv>=0&pv<=1));w<-pr;w[pv>=.05]<-0;add(paste(t,manifest$run_id[i],'aggregate reconciles'),max(abs(apply(w,c(1,2),sum)-z$net$weight))<1e-9)}
 cmp<-fread(file.path(TD(t),'C5_vs_fibro_common_specimen_strength.csv'));add(paste(t,'common-sample comparator only'),all(cmp$C5_eligible&cmp$other_eligible))
 for(kind in c('LR','pathway')){ss<-fread(file.path(OUT,'04_patient_level_summary',paste0('C5_',kind,'_summary_t',t,'.csv.gz')));add(paste(t,kind,'patient denominators'),all(ss$positive_patients<=ss$eligible_patients)&all(ss$positive_specimens<=ss$eligible_specimens));add(paste(t,kind,'NA absent support'),all(is.na(ss[eligible_patients==0,patient_prevalence])))}
}
writecsv(rbindlist(checks),file.path(OUT,'00_audit/final_validation.csv'));writeLines(capture.output(sessionInfo()),file.path(OUT,'00_audit/sessionInfo_final.txt'));cat('FINAL VALIDATION PASS ',k,' checks\n')
